    process.stderr.write(`Error: run-id file not found at ${runIdPath}\n`);
    process.exit(1);
  }
  const runId = fs.readFileSync(runIdPath, 'utf8').trim();
  if (!runId) {
    process.stderr.write(`Error: run-id file at ${runIdPath} is empty\n`);
    process.exit(1);
